package com.example.starter.artifact;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态码，由全局异常处理器转换为错误响应。
 * 抛出后当前事务回滚，失败的写操作不占用幂等键。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;

    public ApiException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus status() {
        return status;
    }
}

package com.example.starter.artifact.dto;

/**
 * 统一错误响应体。
 *
 * @param error   错误类别（HTTP 状态短语）
 * @param message 面向调用方的错误描述
 */
public record ErrorResponse(String error, String message) {
}

package com.example.starter.artifact.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * 依赖声明：闭区间 [minVersion, maxVersion]。
 *
 * @param name       依赖的制品名称
 * @param minVersion 最低版本（含），正整数
 * @param maxVersion 最高版本（含），正整数，须大于等于 minVersion
 */
public record DependencyDto(
        @NotBlank @Size(max = 128) @Pattern(regexp = "[A-Za-z0-9][A-Za-z0-9._-]*") String name,
        @Min(1) @Max(Integer.MAX_VALUE) int minVersion,
        @Min(1) @Max(Integer.MAX_VALUE) int maxVersion) {
}

package com.example.starter.artifact.dto;

import java.util.List;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * 制品登记请求。name + version 联合唯一，创建后依赖不可改。
 *
 * @param requestId    全局唯一幂等请求 id
 * @param name         制品名称
 * @param version      制品版本，正整数
 * @param dependencies 依赖声明，0~10 条，名称唯一；null 视为空
 */
public record RegisterArtifactRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 128) @Pattern(regexp = "[A-Za-z0-9][A-Za-z0-9._-]*") String name,
        @Min(1) int version,
        @Size(max = 10) List<@Valid DependencyDto> dependencies) {
}

package com.example.starter.artifact.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 制品撤回请求。撤回仅标记不删除，仓库版本加一。
 *
 * @param requestId 全局唯一幂等请求 id
 */
public record RetractRequest(@NotBlank @Size(max = 64) String requestId) {
}

package com.example.starter.artifact.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * 锁定请求：指定精确根版本与期望的仓库版本。
 *
 * @param requestId                  全局唯一幂等请求 id
 * @param rootName                   根制品名称，必须存在且未撤回
 * @param rootVersion                根制品精确版本，正整数
 * @param expectedRepositoryVersion  期望的仓库版本，不符返回 409
 */
public record LockRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 128) @Pattern(regexp = "[A-Za-z0-9][A-Za-z0-9._-]*") String rootName,
        @Min(1) int rootVersion,
        @Min(0) long expectedRepositoryVersion) {
}

